functions._assert_document_submission_available:
def _assert_document_submission_available(
    service_case,
    document_title,
    document_type,
):
    title_key = _document_identity(document_title)
    type_key = _document_identity(document_type)

    existing = frappe.get_all(
        "OMC Service Document",
        filters={
            "service_request": service_case.name,
            "visible_to_customer": 1,
        },
        fields=[
            "name",
            "document_title",
            "document_type",
            "status",
            "is_archived",
        ],
        order_by="creation desc",
    )

    for row in existing:
        if int(getattr(row, "is_archived", 0) or 0):
            continue
        if _document_identity(row.document_title) != title_key:
            continue
        if _document_identity(row.document_type) != type_key:
            continue

        status = (row.status or "").strip()
        if status in ACTIVE_DOCUMENT_STATUSES:
            frappe.throw(
                (
                    f"{document_title} already has an active submission "
                    f"with status {status}. Review that document before "
                    "uploading another copy."
                ),
                frappe.ValidationError,
            )

functions._cleanup_failed_unlinked_upload:
def _cleanup_failed_unlinked_upload(uploaded_file):
    if not uploaded_file:
        return False

    if uploaded_file.owner and uploaded_file.owner != _current_user():
        return False

    if uploaded_file.attached_to_doctype or uploaded_file.attached_to_name:
        return False

    frappe.delete_doc(
        "File",
        uploaded_file.name,
        ignore_permissions=True,
        force=True,
    )
    return True

functions._validate_uploaded_document:
def _validate_uploaded_document(service_case, attachment):
    clean_attachment = _clean_file_reference(attachment)
    if not clean_attachment:
        frappe.throw("attachment is required")

    extension = _document_extension(clean_attachment)
    if extension not in ALLOWED_DOCUMENT_EXTENSIONS:
        frappe.throw("Unsupported document type. Please upload PDF, JPG, PNG, DOC or DOCX files only.")

    existing_count = frappe.db.count(
        "OMC Service Document",
        {
            "service_request": service_case.name,
            "visible_to_customer": 1,
        },
    )
    if existing_count >= MAX_FILES_PER_CASE:
        frappe.throw("Maximum document limit reached for this service request.")

    uploaded_file = _find_uploaded_file(clean_attachment)
    if not uploaded_file:
        frappe.throw(
            "Uploaded file could not be verified. Please upload the file again.",
            frappe.DoesNotExistError,
        )

    file_extension = _document_extension(
        uploaded_file.file_name or uploaded_file.file_url or clean_attachment
    )
    if file_extension not in ALLOWED_DOCUMENT_EXTENSIONS:
        frappe.throw("Unsupported document type. Please upload PDF, JPG, PNG, DOC or DOCX files only.")

    file_size = int(uploaded_file.file_size or 0)
    if file_size <= 0:
        frappe.throw("Uploaded file is empty.")
    if file_size > MAX_DOCUMENT_SIZE_BYTES:
        frappe.throw("Document is too large. Maximum allowed size is 10 MB.")

    current_user = _current_user()
    if uploaded_file.owner and uploaded_file.owner != current_user:
        frappe.throw("You do not have permission to use this uploaded file.", frappe.PermissionError)

    allowed_doctypes = {"", "OMC Service Request", "OMC Service Document"}
    if uploaded_file.attached_to_doctype and uploaded_file.attached_to_doctype not in allowed_doctypes:
        frappe.throw("Uploaded file is attached to another document.", frappe.PermissionError)

    if (
        uploaded_file.attached_to_name
        and uploaded_file.attached_to_name != service_case.name
    ):
        frappe.throw(
            "Uploaded file is attached to another service request.",
            frappe.PermissionError,
        )

    return uploaded_file.file_url or clean_attachment, uploaded_file

functions.get_documents:
def get_documents(show_archived=None, queue=None, customer=None, service_request=None, status=None):
    is_internal = _can_access_internal_workspace()
    profile = None if is_internal else _assert_approved_customer()
    allowed_service_requests = None

    if is_internal:
        _user, capabilities, allowed_service_requests = (
            mobile._require_service_case_read_scope()
        )
        _require_document_read_access(capabilities)
    else:
        capabilities = _canonical_capabilities()

    service_filters = {}
    if profile:
        service_filters["customer_profile"] = profile.name
    elif customer:
        service_filters["customer_profile"] = customer

    if service_request:
        if (
            allowed_service_requests is not None
            and service_request not in allowed_service_requests
        ):
            return {"documents": []}
        service_filters["name"] = service_request
    elif allowed_service_requests is not None:
        service_filters["name"] = [
            "in",
            allowed_service_requests or ["__no_service_requests__"],
        ]

    service_request_names = frappe.get_all(
        "OMC Service Request",
        filters=service_filters,
        pluck="name",
    )

    if not service_request_names:
        return {"documents": []}

    filters = {
        "service_request": ["in", service_request_names],
    }

    # Customer app view must never expose internal-only rows. Admin/review center
    # intentionally sees every service document, including archived/history rows.
    if not is_internal:
        filters["visible_to_customer"] = 1

    if status:
        filters["status"] = status

    if _has_field("OMC Service Document", "is_archived"):
        if show_archived in ("1", 1, True, "true", "True"):
            filters["is_archived"] = 1
        elif show_archived in ("0", 0, False, "false", "False"):
            filters["is_archived"] = 0

    queue_key = (queue or "").strip().lower()
    if queue_key in {"needs_review", "review"}:
        filters["status"] = ["in", ["Pending", "Uploaded"]]
        if _has_field("OMC Service Document", "is_archived"):
            filters["is_archived"] = 0
    elif queue_key == "rejected":
        filters["status"] = "Rejected"
    elif queue_key == "approved":
        filters["status"] = "Approved"
    elif queue_key == "missing":
        filters["status"] = "Pending"
    elif queue_key == "archived" and _has_field("OMC Service Document", "is_archived"):
        filters["is_archived"] = 1

    docs = frappe.get_all(
        "OMC Service Document",
        filters=filters,
        fields=_document_fields(),
        order_by="uploaded_on desc, creation desc",
    )

    service_cases = _service_case_map({doc.service_request for doc in docs})
    customer_profiles = _customer_profile_map(
        {
            getattr(doc, "customer_profile", None)
            or getattr(service_cases.get(doc.service_request), "customer_profile", None)
            for doc in docs
        }
    )

    return {
        "documents": [
            _document_dict(
                doc,
                service_case=service_cases.get(doc.service_request),
                customer_profile=customer_profiles.get(
                    getattr(doc, "customer_profile", None)
                    or getattr(service_cases.get(doc.service_request), "customer_profile", None)
                ),
                capabilities=capabilities,
            )
            for doc in docs
        ]
    }

functions.get_document:
def get_document(document_id=None):
    if not document_id:
        frappe.throw("document_id is required")

    if not frappe.db.exists("OMC Service Document", document_id):
        frappe.throw("Document not found", frappe.DoesNotExistError)

    doc = frappe.get_doc("OMC Service Document", document_id)
    is_internal = _can_access_internal_workspace()

    if not is_internal and not doc.visible_to_customer:
        frappe.throw("Document not found", frappe.DoesNotExistError)

    profile = None if is_internal else _assert_approved_customer()
    if is_internal:
        _user, capabilities, _allowed_service_requests = (
            mobile._require_service_case_read_scope(doc.service_request)
        )
        _require_document_read_access(capabilities)
    else:
        capabilities = _canonical_capabilities()
    service_case = frappe.get_doc("OMC Service Request", doc.service_request)

    if profile and service_case.customer_profile and service_case.customer_profile != profile.name:
        frappe.throw("You do not have permission to access this document", frappe.PermissionError)

    customer_profiles = _customer_profile_map([getattr(service_case, "customer_profile", None)])
    return _document_dict(
        doc,
        service_case=service_case,
        customer_profile=customer_profiles.get(getattr(service_case, "customer_profile", None)),
        capabilities=capabilities,
    )

functions.update_service_document_status:
def update_service_document_status(
    document_id=None,
    status=None,
    remarks=None,
):
    _require_document_review_access()

    if not document_id:
        frappe.throw("document_id is required")
    if not status:
        frappe.throw("status is required")

    allowed_statuses = ["Pending", "Uploaded", "Approved", "Rejected"]
    if status not in allowed_statuses:
        frappe.throw("Invalid document status")

    if not frappe.db.exists("OMC Service Document", document_id):
        frappe.throw(
            "Service document not found",
            frappe.DoesNotExistError,
        )

    doc = frappe.get_doc("OMC Service Document", document_id)
    mobile._require_service_case_read_scope(doc.service_request)

    service_case = frappe.get_doc(
        "OMC Service Request",
        doc.service_request,
    )
    service_status = (service_case.status or "").strip()
    if service_status in ARCHIVE_SERVICE_STATUSES:
        frappe.throw(
            (
                "Documents cannot be reviewed after a service request is "
                f"{service_status.lower()}."
            ),
            frappe.ValidationError,
        )

    old_status = (doc.status or "").strip()
    clean_remarks = (remarks or "").strip()

    if old_status == status:
        return {
            "name": doc.name,
            "case_id": doc.service_request,
            "status": old_status,
            "updated": False,
            "message": "No document status change.",
            "payment_id": None,
            "case_status": service_status,
        }

    final_statuses = {"Approved", "Rejected"}
    if old_status in final_statuses:
        frappe.throw(
            (
                f"A {old_status.lower()} document review is final. "
                "Upload a corrected document instead of changing this record."
            ),
            frappe.ValidationError,
        )

    allowed_transitions = {
        "Pending": {"Uploaded", "Approved", "Rejected"},
        "Uploaded": {"Approved", "Rejected"},
        "": {"Pending", "Uploaded", "Approved", "Rejected"},
    }
    if status not in allowed_transitions.get(old_status, set()):
        frappe.throw(
            f"Invalid document status transition: {old_status or 'None'} to {status}.",
            frappe.ValidationError,
        )

    if status == "Rejected" and not clean_remarks:
        frappe.throw(
            "Review remarks are required when rejecting a document.",
            frappe.ValidationError,
        )

    doc.status = status

    if remarks is not None:
        if _has_field("OMC Service Document", "review_remarks"):
            doc.review_remarks = clean_remarks
        doc.remarks = clean_remarks

    if status in final_statuses:
        if _has_field("OMC Service Document", "reviewed_by"):
            doc.reviewed_by = frappe.session.user
        if _has_field("OMC Service Document", "reviewed_on"):
            doc.reviewed_on = frappe.utils.now_datetime()

    doc.save(ignore_permissions=True)

    from omc_app.api import payments
    from omc_app.api.mobile import _create_service_timeline_entry

    _create_service_timeline_entry(
        service_request=doc.service_request,
        event_type="Update",
        title=f"Document {status}",
        description=(
            clean_remarks
            or f"{doc.document_title or 'Document'} marked as {status}."
        ),
        visible_to_customer=1,
    )
    automation = payments.handle_document_review(
        doc.service_request,
        status,
        remarks=clean_remarks,
    )

    frappe.db.commit()

    return {
        "name": doc.name,
        "case_id": doc.service_request,
        "status": doc.status,
        "updated": True,
        "message": "Service document updated.",
        "payment_id": automation.get("payment"),
        "case_status": automation.get("case_status"),
    }

functions._set_case_status:
def _set_case_status(service_case, status):
    if not service_case or service_case.status in {"Completed", "Cancelled"}:
        return False
    if service_case.status == status:
        return False
    service_case.status = status
    service_case.save(ignore_permissions=True)
    return True

functions._approved_required_documents:
def _approved_required_documents(service_case):
    required_templates = mobile._service_required_documents(
        service_case.service
    )

    uploaded_docs = frappe.get_all(
        "OMC Service Document",
        filters={
            "service_request": service_case.name,
            "visible_to_customer": 1,
        },
        fields=[
            "document_title",
            "document_type",
            "status",
            "attachment",
        ],
    )

    documents = [
        {
            "document_title": doc.document_title or "",
            "document_type": doc.document_type or "",
            "status": doc.status or "",
            "attachment": doc.attachment or "",
        }
        for doc in uploaded_docs
    ]

    return mobile._required_documents_complete(
        required_templates,
        documents,
    )

functions.handle_document_review:
def handle_document_review(service_request, status, remarks=None):
    if not service_request or not frappe.db.exists(
        "OMC Service Request", service_request
    ):
        return {"payment": None, "case_status": None}

    service_case = frappe.get_doc("OMC Service Request", service_request)
    normalized = _clean_text(status).lower()
    payment_name = None

    if normalized == "rejected":
        changed = _set_case_status(service_case, "Waiting for Customer")
        message = remarks or (
            "A document needs correction. Review the rejection reason and upload "
            "a replacement document."
        )
        _notify_customer(
            service_case,
            title="Document needs attention",
            message=message,
            notification_type="Document",
        )
        if changed:
            mobile._create_service_timeline_entry(
                service_request=service_case.name,
                event_type="Status Updated",
                title="Waiting for Customer",
                description="The request is waiting for a corrected document.",
                visible_to_customer=1,
            )

    elif normalized == "approved":
        payment_name = _ensure_payment_for_case(service_case)
        if not payment_name:
            _notify_customer(
                service_case,
                title="Document approved",
                message=remarks or "Your document has been approved.",
                notification_type="Document",
            )

    return {
        "payment": payment_name,
        "case_status": service_case.status,
    }

functions.completion_blockers:
def completion_blockers(service_case):
    blockers = []

    required_templates = mobile._service_required_documents(service_case.service)
    required_templates = [
        row for row in required_templates if row.get("is_required")
    ]
    if required_templates:
        approved = frappe.get_all(
            "OMC Service Document",
            filters={
                "service_request": service_case.name,
                "status": "Approved",
                "attachment": ["is", "set"],
            },
            fields=["document_title", "document_type"],
        )
        approved_keys = {
            (
                (row.document_title or "").strip().lower(),
                (row.document_type or "").strip().lower(),
            )
            for row in approved
        }
        for template in required_templates:
            key = (
                (
                    template.get("title")
                    or template.get("document_title")
                    or ""
                ).strip().lower(),
                (
                    template.get("type")
                    or template.get("document_type")
                    or ""
                ).strip().lower(),
            )
            if key not in approved_keys:
                blockers.append("Required documents are not fully approved.")
                break

    active_payments = frappe.get_all(
        "OMC Service Payment",
        filters={
            "service_request": service_case.name,
            "status": ["not in", ["Cancelled"]],
        },
        fields=["status"],
    )
    if active_payments and any(
        (payment.status or "") != "Paid" for payment in active_payments
    ):
        blockers.append("Required payment has not been confirmed.")

    rejected_documents = frappe.db.count(
        "OMC Service Document",
        filters={
            "service_request": service_case.name,
            "status": "Rejected",
        },
    )
    if rejected_documents:
        blockers.append("Rejected documents still require resolution.")

    rejected_payments = frappe.db.count(
        "OMC Service Payment",
        filters={
            "service_request": service_case.name,
            "status": "Rejected",
        },
    )
    if rejected_payments:
        blockers.append("Rejected payment receipts still require resolution.")

    return blockers

functions._require_capability:
def _require_capability(capability, message):
    capabilities = _capabilities()
    if not capabilities.get(capability):
        frappe.throw(message, frappe.PermissionError)
    return capabilities

functions._assert_support_assignee_allowed:
def _assert_support_assignee_allowed(assigned_to):
    user_values = frappe.db.get_value(
        "User",
        assigned_to,
        ["enabled", "user_type"],
        as_dict=True,
    )
    if not user_values:
        frappe.throw("Assigned user not found", frappe.DoesNotExistError)

    if not int(user_values.enabled or 0):
        frappe.throw(
            "Support tickets can only be assigned to an enabled user.",
            frappe.ValidationError,
        )

    if user_values.user_type != "System User":
        frappe.throw(
            "Support tickets can only be assigned to an internal system user.",
            frappe.PermissionError,
        )

    capabilities = access.get_mobile_capabilities(user=assigned_to)
    if not capabilities.get("can_view_support_tickets"):
        frappe.throw(
            "Assigned user does not have permission to access support tickets.",
            frappe.PermissionError,
        )

functions._clean_file_reference:
def _clean_file_reference(value):
    text_value = (value or "").strip()
    if not text_value:
        return ""
    return text_value.split("?")[0].strip()

functions._file_extension:
def _file_extension(value):
    file_name = _clean_file_reference(value).rsplit("/", 1)[-1]
    if "." not in file_name:
        return ""
    return file_name.rsplit(".", 1)[-1].strip().lower()

functions._find_uploaded_file:
def _find_uploaded_file(file_reference):
    clean_reference = _clean_file_reference(file_reference)
    if not clean_reference:
        return None

    file_name = clean_reference.rsplit("/", 1)[-1]
    for filters in ({"file_url": clean_reference}, {"file_name": file_name}):
        file_docname = frappe.db.exists("File", filters)
        if file_docname:
            return frappe.get_doc("File", file_docname)
    return None

functions._public_file_url:
def _public_file_url(value):
    text = (value or "").strip()
    if not text:
        return ""
    if text.startswith(("http://", "https://")):
        return text
    if text.startswith(("/files/", "/private/files/", "/assets/")):
        return frappe.utils.get_url(text)
    return text

functions._attachment_meta:
def _attachment_meta(file_reference):
    clean_reference = _clean_file_reference(file_reference)
    if not clean_reference:
        return {
            "attachment": "",
            "attachment_url": "",
            "attachment_name": "",
            "attachment_type": "",
            "attachment_size": 0,
        }

    uploaded_file = _find_uploaded_file(clean_reference)
    file_name = ""
    file_size = 0
    if uploaded_file:
        file_name = uploaded_file.file_name or ""
        file_size = int(uploaded_file.file_size or 0)

    if not file_name:
        file_name = clean_reference.rsplit("/", 1)[-1]

    return {
        "attachment": clean_reference,
        "attachment_url": _public_file_url(clean_reference),
        "attachment_name": file_name,
        "attachment_type": _file_extension(file_name or clean_reference),
        "attachment_size": file_size,
    }

functions._assert_support_attachment_allowed:
def _assert_support_attachment_allowed(ticket, file_reference):
    clean_reference = _clean_file_reference(file_reference)
    if not clean_reference:
        return ""

    extension = _file_extension(clean_reference)
    if extension not in ALLOWED_SUPPORT_ATTACHMENT_EXTENSIONS:
        frappe.throw("Unsupported attachment type. Please upload PDF, JPG, PNG, DOC or DOCX files only.")

    uploaded_file = _find_uploaded_file(clean_reference)
    if not uploaded_file:
        return clean_reference

    uploaded_extension = _file_extension(uploaded_file.file_name or uploaded_file.file_url or clean_reference)
    if uploaded_extension not in ALLOWED_SUPPORT_ATTACHMENT_EXTENSIONS:
        frappe.throw("Unsupported attachment type. Please upload PDF, JPG, PNG, DOC or DOCX files only.")

    file_size = int(uploaded_file.file_size or 0)
    if file_size <= 0:
        frappe.throw("Uploaded attachment is empty.")
    if file_size > MAX_SUPPORT_ATTACHMENT_SIZE_BYTES:
        frappe.throw("Attachment is too large. Maximum allowed size is 10 MB.")

    current_user = _current_user()
    if uploaded_file.owner and uploaded_file.owner != current_user and not _can_access_internal_workspace(current_user):
        frappe.throw("You do not have permission to use this uploaded attachment.", frappe.PermissionError)

    if uploaded_file.attached_to_doctype and uploaded_file.attached_to_doctype not in {"", "OMC Support Ticket"}:
        frappe.throw("Uploaded attachment is attached to another document.", frappe.PermissionError)

    if uploaded_file.attached_to_name and uploaded_file.attached_to_name != ticket.name:
        frappe.throw("Uploaded attachment is attached to another support ticket.", frappe.PermissionError)

    if not uploaded_file.is_private:
        uploaded_file.is_private = 1

    if uploaded_file.attached_to_doctype != "OMC Support Ticket" or uploaded_file.attached_to_name != ticket.name:
        uploaded_file.attached_to_doctype = "OMC Support Ticket"
        uploaded_file.attached_to_name = ticket.name

    uploaded_file.save(ignore_permissions=True)
    return uploaded_file.file_url or clean_reference

functions._has_message_doctype:
def _has_message_doctype():
    try:
        return bool(frappe.db.exists("DocType", SUPPORT_MESSAGE_DOCTYPE))
    except Exception:
        return False

functions._message_has_field:
def _message_has_field(fieldname):
    if not _has_message_doctype():
        return False
    try:
        return bool(frappe.get_meta(SUPPORT_MESSAGE_DOCTYPE).has_field(fieldname))
    except Exception:
        return False

functions._support_ticket_messages:
def _support_ticket_messages(ticket):
    if not _has_message_doctype():
        return _legacy_support_ticket_messages(ticket)

    rows = frappe.get_all(
        SUPPORT_MESSAGE_DOCTYPE,
        filters={"support_ticket": ticket.name, "is_internal": 0},
        fields=[
            "name",
            "sender_user",
            "sender_type",
            "message",
            "attachment",
            "is_internal",
            "creation",
            "owner",
        ],
        order_by="creation asc",
        limit_page_length=500,
    )

    if rows:
        return [_message_row_to_dict(row) for row in rows]

    return _legacy_support_ticket_messages(ticket)

functions._assert_support_ticket_access:
def _assert_support_ticket_access(ticket):
    user = _current_user()
    if user == "Guest":
        frappe.throw("You do not have permission to access this support ticket", frappe.PermissionError)

    if _can_access_internal_workspace(user):
        _require_capability(
            "can_view_support_tickets",
            "You do not have permission to access support tickets.",
        )
        return user, None

    profile = _assert_approved_customer()
    if profile and ticket.customer_profile and ticket.customer_profile != profile.name:
        frappe.throw("You do not have permission to access this support ticket", frappe.PermissionError)

    if not profile and ticket.raised_by and ticket.raised_by != user:
        frappe.throw("You do not have permission to access this support ticket", frappe.PermissionError)

    return user, profile

functions._support_ticket_filters_for_current_user:
def _support_ticket_filters_for_current_user():
    user = _current_user()
    if user == "Guest":
        return user, None, None

    if _can_access_internal_workspace(user):
        _require_capability(
            "can_view_support_tickets",
            "You do not have permission to view support tickets.",
        )
        return user, None, {}

    profile = _assert_approved_customer()
    if profile:
        return user, profile, {"customer_profile": profile.name}

    return user, None, {"raised_by": user}

functions._support_message_read_filters:
def _support_message_read_filters(user, profile, mark_read=False):
    if user == "Guest" or not _has_message_doctype():
        return None

    if _can_access_internal_workspace(user):
        if not _message_has_field("read_by_staff"):
            return None
        return {
            "is_internal": 0,
            "sender_type": "Customer",
            "read_by_staff": 0 if not mark_read else ["in", [0, 1]],
        }

    if not _message_has_field("read_by_customer"):
        return None
    return {
        "is_internal": 0,
        "sender_type": ["in", ["Support", "Admin", "System"]],
        "read_by_customer": 0 if not mark_read else ["in", [0, 1]],
    }

functions.get_support_tickets:
def get_support_tickets():
    user, _profile, filters = _support_ticket_filters_for_current_user()
    if user == "Guest" or filters is None:
        return {"tickets": []}

    ticket_names = frappe.get_all(
        "OMC Support Ticket",
        filters=filters,
        pluck="name",
        order_by="modified desc",
        limit_page_length=50,
    )
    return {"tickets": [_support_ticket_to_dict(frappe.get_doc("OMC Support Ticket", name)) for name in ticket_names]}

functions.get_support_ticket:
def get_support_ticket(ticket_id=None, name=None):
    ticket_id = ticket_id or name
    if not ticket_id:
        frappe.throw("ticket_id is required")
    if not frappe.db.exists("OMC Support Ticket", ticket_id):
        frappe.throw("Support ticket not found", frappe.DoesNotExistError)

    ticket = frappe.get_doc("OMC Support Ticket", ticket_id)
    _assert_support_ticket_access(ticket)
    return {"ticket": _support_ticket_to_dict(ticket)}

functions.get_active_support_ticket:
def get_active_support_ticket():
    user, _profile, filters = _support_ticket_filters_for_current_user()
    if user == "Guest" or filters is None:
        return {"ticket": None}

    active_filters = dict(filters)
    active_filters["status"] = ["not in", ["Closed", "Cancelled"]]
    ticket_names = frappe.get_all(
        "OMC Support Ticket",
        filters=active_filters,
        pluck="name",
        order_by="modified desc",
        limit_page_length=1,
    )
    if not ticket_names:
        return {"ticket": None}

    ticket = frappe.get_doc("OMC Support Ticket", ticket_names[0])
    _assert_support_ticket_access(ticket)
    return {"ticket": _support_ticket_to_dict(ticket)}

functions.get_support_unread_count:
def get_support_unread_count():
    user, profile, ticket_filters = _support_ticket_filters_for_current_user()
    if user == "Guest" or ticket_filters is None:
        return {"count": 0}

    message_filters = _support_message_read_filters(user, profile)
    if not message_filters:
        return {"count": 0}

    ticket_names = frappe.get_all("OMC Support Ticket", filters=ticket_filters, pluck="name")
    if not ticket_names:
        return {"count": 0}

    message_filters["support_ticket"] = ["in", ticket_names]
    return {"count": frappe.db.count(SUPPORT_MESSAGE_DOCTYPE, message_filters)}

functions.mark_support_ticket_read:
def mark_support_ticket_read(ticket_id=None, name=None):
    ticket_id = ticket_id or name
    if not ticket_id:
        frappe.throw("ticket_id is required")
    if not frappe.db.exists("OMC Support Ticket", ticket_id):
        frappe.throw("Support ticket not found", frappe.DoesNotExistError)

    ticket = frappe.get_doc("OMC Support Ticket", ticket_id)
    user, profile = _assert_support_ticket_access(ticket)
    _ensure_initial_message_record(ticket)

    message_filters = _support_message_read_filters(user, profile, mark_read=True)
    if not message_filters:
        return {"updated": 0}

    message_filters["support_ticket"] = ticket.name
    message_names = frappe.get_all(SUPPORT_MESSAGE_DOCTYPE, filters=message_filters, pluck="name")
    read_field = "read_by_staff" if _can_access_internal_workspace(user) else "read_by_customer"

    for message_name in message_names:
        frappe.db.set_value(SUPPORT_MESSAGE_DOCTYPE, message_name, read_field, 1, update_modified=False)

    frappe.db.commit()
    return {"updated": len(message_names)}

functions.add_support_ticket_reply:
def add_support_ticket_reply(ticket_id=None, message=None, **kwargs):
    ticket_id = ticket_id or kwargs.get("name")
    message = (message or kwargs.get("reply") or kwargs.get("description") or "").strip()
    attachment = kwargs.get("attachment") or kwargs.get("file_url") or kwargs.get("file") or ""

    if not ticket_id:
        frappe.throw("ticket_id is required")
    if not message and not attachment:
        frappe.throw("message or attachment is required")
    if not frappe.db.exists("OMC Support Ticket", ticket_id):
        frappe.throw("Support ticket not found", frappe.DoesNotExistError)

    ticket = frappe.get_doc("OMC Support Ticket", ticket_id)
    user, _profile = _assert_support_ticket_access(ticket)

    if ticket.status in ["Closed", "Cancelled"]:
        frappe.throw("This support ticket is closed. Please reopen it before replying.")

    _ensure_initial_message_record(ticket)
    is_internal_user = _can_access_internal_workspace(user)
    if is_internal_user:
        _require_capability(
            "can_reply_support_tickets",
            "You do not have permission to reply to support tickets.",
        )
    sender_type = "Support" if is_internal_user else "Customer"
    _create_support_message(ticket, message=message, attachment=attachment, sender_type=sender_type)

    if not is_internal_user and ticket.status in ["Resolved", "Waiting for Customer"]:
        ticket.status = "Open"
        ticket.closed_on = None
    elif is_internal_user and ticket.status == "Open":
        ticket.status = "In Progress"
    ticket.save(ignore_permissions=True)

    if is_internal_user and ticket.customer_profile:
        _create_customer_notification(
            customer_profile=ticket.customer_profile,
            title="Support reply received",
            message=message or "OMC support added an attachment to your ticket.",
            notification_type="Support",
            reference_doctype="OMC Support Ticket",
            reference_name=ticket.name,
        )

    frappe.db.commit()
    return {"updated": True, "ticket": _support_ticket_to_dict(ticket), "message": "Support reply added."}

functions.update_support_ticket_status:
def update_support_ticket_status(ticket_id=None, status=None, remarks=None, **kwargs):
    ticket_id = ticket_id or kwargs.get("name")
    allowed_statuses = {"Open", "In Progress", "Waiting for Customer", "Resolved", "Closed", "Cancelled"}

    if not ticket_id:
        frappe.throw("ticket_id is required")
    if not status:
        frappe.throw("status is required")
    if status not in allowed_statuses:
        frappe.throw("status must be one of: Open, In Progress, Waiting for Customer, Resolved, Closed, Cancelled")
    if not frappe.db.exists("OMC Support Ticket", ticket_id):
        frappe.throw("Support ticket not found", frappe.DoesNotExistError)

    ticket = frappe.get_doc("OMC Support Ticket", ticket_id)
    user, _profile = _assert_support_ticket_access(ticket)
    if not _can_access_internal_workspace(user):
        frappe.throw(
            "You do not have permission to update support ticket status.",
            frappe.PermissionError,
        )
    _require_capability(
        "can_update_support_ticket_status",
        "You do not have permission to update support ticket status.",
    )

    old_status = ticket.status or ""
    ticket.status = status
    ticket.closed_on = frappe.utils.now_datetime() if status in ["Resolved", "Closed", "Cancelled"] else None

    if remarks:
        _ensure_initial_message_record(ticket)
        _create_support_message(ticket, message=remarks, sender_type="Support")

    ticket.save(ignore_permissions=True)

    if ticket.customer_profile:
        _create_customer_notification(
            customer_profile=ticket.customer_profile,
            title=f"Support Ticket {status}",
            message=remarks or f"Your support ticket '{ticket.subject or ticket.name}' is now {status}.",
            notification_type="Support",
            reference_doctype="OMC Support Ticket",
            reference_name=ticket.name,
        )

    frappe.db.commit()
    return {"updated": True, "old_status": old_status, "ticket": _support_ticket_to_dict(ticket), "message": "Support ticket status updated."}

functions.assign_support_ticket:
def assign_support_ticket(ticket_id=None, assigned_to=None, **kwargs):
    ticket_id = ticket_id or kwargs.get("name")
    assigned_to = (assigned_to or kwargs.get("user") or "").strip()

    if not ticket_id:
        frappe.throw("ticket_id is required")
    if not assigned_to:
        frappe.throw("assigned_to is required")
    if not frappe.db.exists("OMC Support Ticket", ticket_id):
        frappe.throw("Support ticket not found", frappe.DoesNotExistError)
    _assert_support_assignee_allowed(assigned_to)

    ticket = frappe.get_doc("OMC Support Ticket", ticket_id)
    user, _profile = _assert_support_ticket_access(ticket)
    if not _can_access_internal_workspace(user):
        frappe.throw(
            "You do not have permission to assign support tickets.",
            frappe.PermissionError,
        )
    _require_capability(
        "can_assign_support_tickets",
        "You do not have permission to assign support tickets.",
    )

    previous_user = ticket.assigned_to or ""
    ticket.assigned_to = assigned_to
    if ticket.status == "Open":
        ticket.status = "In Progress"
    ticket.save(ignore_permissions=True)

    _ensure_initial_message_record(ticket)
    assignment_note = f"Ticket assigned to {assigned_to}."
    if previous_user and previous_user != assigned_to:
        assignment_note = f"Ticket transferred from {previous_user} to {assigned_to}."
    _create_support_message(ticket, message=assignment_note, sender_type="System")

    frappe.db.commit()
    return {"updated": True, "ticket": _support_ticket_to_dict(ticket), "message": assignment_note}
